#!/usr/bin/env python3
# -*- coding: utf-8 -*-
r"""makereport_all.py — CSV/JSON 진단결과 → 결과보고서(xlsx) 단일 파일(자동 생성, 편집 금지).
양식·변환코드를 내장한다. build_report_onefile.py 로 재생성.

사용(파이썬3 + lxml 필요):
  python makereport_all.py <입력폴더>            # 폴더 안 CSV/JSON 전부 → reports_out/
  python makereport_all.py a.csv b.csv           # 파일 지정
  python makereport_all.py --kind linux x.csv    # 종류 직접 지정
"""
import base64 as _b64, os as _os, sys as _sys, tempfile as _tf

_EMBED = {
    'make_reports.py': '',
    'make_report.py': '',
    'server_report.py': '',
    'tpl_xml.py': '',
    '보고서_양식_AWS.xlsx': '',
    '보고서_양식_Azure.xlsx': '',
    '보고서_양식_DBMS.xlsx': '',
    '보고서_양식_GCP.xlsx': '',
    '보고서_양식_Linux.xlsx': '',
    '보고서_양식_Naver.xlsx': '',
    '보고서_양식_Webserver.xlsx': '',
    '보고서_양식_Windows.xlsx': '',
}

_EMBED_ID = 'a90b18c84bf8'

def _bootstrap():
    d = _os.path.join(_tf.gettempdir(), 'makereport_embed_' + _EMBED_ID)
    for _name, _b in _EMBED.items():
        _p = _os.path.join(d, _name)
        _os.makedirs(_os.path.dirname(_p), exist_ok=True)
        _data = _b64.b64decode(_b)
        try:
            with open(_p, 'rb') as _f: _cur = _f.read()
        except OSError:
            _cur = None
        if _cur != _data:
            with open(_p, 'wb') as _f: _f.write(_data)
    _os.environ['INFRA_DIR'] = d
    if d in _sys.path: _sys.path.remove(d)
    _sys.path.insert(0, d)
    return d

_DIR = _bootstrap()
try:
    import lxml.etree  # noqa: F401
except Exception:
    _sys.exit('[!] lxml 이 필요합니다:  pip install lxml   (또는 pip3 install --user lxml)')
import make_reports  # noqa: E402

if __name__ == '__main__':
    make_reports.main()
